SELECT jsonb_build_object('runtime_roles',(SELECT count(*) FROM pg_authid WHERE rolname IN ('wa_context_issuer','wa_identity_service_authority','wa_app_runtime','wa_worker')),'all_null_verifiers',(SELECT bool_and(rolpassword IS NULL) FROM pg_authid WHERE rolname IN ('wa_context_issuer','wa_identity_service_authority','wa_app_runtime','wa_worker')),'flags_exact',(SELECT bool_and(rolcanlogin AND NOT rolsuper AND NOT rolbypassrls AND NOT rolinherit AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication) FROM pg_authid WHERE rolname IN ('wa_context_issuer','wa_identity_service_authority','wa_app_runtime','wa_worker')));
